&lt;div id=&quot;richTextArea.jobPosting.jobDescription-input--uid95-input&quot; class=&quot;WOEY WCGY WADY WBGY WF5 WPEY&quot; data-automation-id=&quot;richTextEditor&quot;&gt;
&lt;div class=&quot;GWTCKEditor-Disabled&quot;&gt;
&lt;p&gt;&lt;strong&gt;Requirements&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Academic background in Electrical or Computer Engineering&lt;/li&gt;
